parameters.jsCode:
const response = $json;
const text = response.output?.flatMap((item) => item.content ?? []).find((content) => content.type === 'output_text')?.text ?? response.output_text;
if (typeof text !== 'string' || !text.trim()) throw new Error('OpenAI response does not contain output_text');
let analysis;
try { analysis = JSON.parse(text); } catch { throw new Error('OpenAI output is not valid JSON'); }
const priorities = new Set(['High', 'Medium', 'Low']);
const categories = new Set(['schedule', 'task', 'notice', 'invoice', 'promotion', 'other']);
const keys = ['summary', 'priority', 'category', 'requiresAction', 'isSchedule', 'event'];
if (!keys.every((key) => Object.hasOwn(analysis, key))) throw new Error('OpenAI output is missing required fields');
if (typeof analysis.summary !== 'string' || !analysis.summary.trim()) throw new Error('summary must be a non-empty string');
if (!priorities.has(analysis.priority)) throw new Error('priority is invalid');
if (!categories.has(analysis.category)) throw new Error('category is invalid');
if (typeof analysis.requiresAction !== 'boolean' || typeof analysis.isSchedule !== 'boolean') throw new Error('boolean fields are invalid');
if (analysis.isSchedule) {
  if (!analysis.event || typeof analysis.event.title !== 'string' || !analysis.event.title.trim()) throw new Error('Scheduled email is missing event title');
  if (typeof analysis.event.startDateTime !== 'string' || Number.isNaN(Date.parse(analysis.event.startDateTime))) throw new Error('Scheduled email is missing a valid startDateTime');
}
if (!analysis.isSchedule && analysis.event !== null) throw new Error('Non-schedule email must have a null event');
return [{ json: analysis }];
